// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';


export type BusinessGrowthProps = Record<string, any>;

const BusinessGrowth: React.FC<BusinessGrowthProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = true,
  durationInSeconds = 5,
  barColorPrimary = "#2563eb",
  barColorSecondary = "#93c5fd",
  trendLineColor = "#10b981",
  gridLineColor = "#e2e8f0",
  barCount = 5,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Canvas Coordinates (Internal ViewBox 1000x1400)
  const SVG_WIDTH = 1000;
  const SVG_HEIGHT = 1400;
  const CHART_X = 100;
  const CHART_Y_BOTTOM = 1200;
  const CHART_WIDTH = 850;
  const CHART_HEIGHT = 1000;

  // Timing logic
  const START_BARS = 10;
  const START_GROWTH = 50;

  // Global Grid & Axes Entrance
  const gridProgress = spring({
    fps,
    frame,
    config: { damping: 20, mass: 1 },
  });

  // Global Growth Sequence (Transforms flat chart into exponential curve)
  const growthProgress = spring({
    fps,
    frame: frame - START_GROWTH,
    config: { damping: 16, mass: 1.5 },
  });

  // Pre-calculate bar properties and current animation states
  const availableBarSpace = CHART_WIDTH * 0.7;
  const availableGapSpace = CHART_WIDTH * 0.3;
  const barW = availableBarSpace / barCount;
  const gapW = availableGapSpace / (barCount + 1);

  const barStates = Array.from({ length: barCount }).map((_, i) => {
    const startX = CHART_X + gapW + i * (barW + gapW);
    const centerX = startX + barW / 2;

    const t = barCount > 1 ? i / (barCount - 1) : 1;
    
    // Initial state: a slow, flat linear growth
    const initialH = 100 + t * 100;
    // Target state: aggressive exponential growth
    const targetH = 100 + Math.pow(t, 2.5) * (CHART_HEIGHT - 100);

    const entrance = spring({
      fps,
      frame: frame - (START_BARS + i * 4),
      config: { damping: 14, mass: 0.8 },
    });

    // Height interpolates between initial and target based on the global growth phase
    const currentH = (initialH + (targetH - initialH) * growthProgress) * entrance;
    const currentY = CHART_Y_BOTTOM - currentH;

    return { startX, centerX, barW, currentH, currentY, entrance };
  });

  // Build Path for Trend Line
  const pathD = barStates
    .map((b, i) => `${i === 0 ? "M" : "L"} ${b.centerX} ${b.currentY}`)
    .join(" ");

  // Opacities and Scales for overlay elements (line, dots, arrow)
  const overlayOpacity = interpolate(frame, [START_GROWTH - 5, START_GROWTH + 10], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const dotScale = interpolate(frame, [START_GROWTH, START_GROWTH + 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Calculate Arrowhead Position and Rotation
  const lastBar = barStates[barStates.length - 1];
  const prevBar = barStates[barStates.length - 2] || barStates[0];
  const angle = Math.atan2(
    lastBar.currentY - prevBar.currentY,
    lastBar.centerX - prevBar.centerX
  ) * (180 / Math.PI);

  // Grid Lines calculations
  const gridLines = [0.25, 0.5, 0.75, 1];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, display: "flex", alignItems: "center", justifyContent: "center" }}>
      <div style={{ width: "100%", height: "100%", display: "flex", alignItems: "center", justifyContent: "center" }}>
        <svg
          viewBox={`0 0 ${SVG_WIDTH} ${SVG_HEIGHT}`}
          style={{ width: "85%", maxWidth: "900px", overflow: "visible" }}
        >
          <defs>
            <linearGradient id="barGradient" x1="0" y1="1" x2="0" y2="0">
              <stop offset="0%" stopColor={barColorSecondary} />
              <stop offset="100%" stopColor={barColorPrimary} />
            </linearGradient>
            <filter id="glow" x="-20%" y="-20%" width="140%" height="140%">
              <feGaussianBlur stdDeviation="15" result="blur" />
              <feComposite in="SourceGraphic" in2="blur" operator="over" />
            </filter>
          </defs>

          {/* Grid Lines */}
          {gridLines.map((pct, i) => {
            const y = CHART_Y_BOTTOM - pct * CHART_HEIGHT;
            return (
              <line
                key={`grid-${i}`}
                x1={CHART_X}
                y1={y}
                x2={CHART_X + CHART_WIDTH * gridProgress}
                y2={y}
                stroke={gridLineColor}
                strokeWidth={2}
                strokeDasharray="10 10"
                style={{ transition: "none" }}
              />
            );
          })}

          {/* Base X-Axis */}
          <line
            x1={CHART_X - 20}
            y1={CHART_Y_BOTTOM}
            x2={CHART_X + CHART_WIDTH * gridProgress}
            y2={CHART_Y_BOTTOM}
            stroke={gridLineColor}
            strokeWidth={4}
            strokeLinecap="round"
            style={{ transition: "none" }}
          />

          {/* Bars */}
          {barStates.map((b, i) => (
            <rect
              key={`bar-${i}`}
              x={b.startX}
              y={b.currentY}
              width={b.barW}
              height={Math.max(0, b.currentH)}
              fill="url(#barGradient)"
              rx={12}
              style={{ transition: "none" }}
            />
          ))}

          {/* Trend Line (Fades in during growth phase) */}
          <path
            d={pathD}
            stroke={trendLineColor}
            strokeWidth={8}
            fill="none"
            strokeLinecap="round"
            strokeLinejoin="round"
            opacity={overlayOpacity}
            style={{ transition: "none" }}
          />

          {/* Dots on Trend Line */}
          {barStates.map((b, i) => (
            <circle
              key={`dot-${i}`}
              cx={b.centerX}
              cy={b.currentY}
              r={10 * dotScale}
              fill={backgroundColor === "transparent" || transparentBackground ? "#ffffff" : backgroundColor}
              stroke={trendLineColor}
              strokeWidth={5}
              style={{ transition: "none" }}
            />
          ))}

          {/* Arrowhead at the end of the line */}
          <g
            transform={`translate(${lastBar.centerX}, ${lastBar.currentY}) rotate(${angle}) scale(${dotScale})`}
            opacity={overlayOpacity}
            style={{ transition: "none" }}
          >
            <path
              d="M -20 -15 L 5 0 L -20 15 L -10 0 Z"
              fill={trendLineColor}
              style={{ transition: "none" }}
            />
          </g>
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default BusinessGrowth;